def fizzbuzz(n: int) -> list[str]:
    """
    Devuelve una lista de strings del 1 al n, donde:
      - Multiplos de 3 son 'Fizz'
      - Multiplos de 5 son 'Buzz'
      - Multiplos de 3 y 5 son 'FizzBuzz'
      - Los demás son los números como string.
    """
    result = []
    for i in range(1, n + 1):
        if i % 3 == 0 and i % 5 == 0:
            result.append("FizzBuzz")
        elif i % 3 == 0:
            result.append("Fizz")
        elif i % 5 == 0:
            result.append("Buzz")
        else:
            result.append(str(i))
    return result

def a_romano(n: int) -> str:
    """Convierte un entero entre 1 y 3999 a su representación en números romanos usando notación sustractiva."""
    if n < 1 or n > 3999:
        raise ValueError("El número debe estar entre 1 y 3999.")

    if n == 0:
        return "0"

    # Definición de los valores de los símbolos
    values = [1000, 900, 500, 400, 100, 90, 50, 40, 10, 9, 5, 4, 1]
    symbols = ["M", "CM", "D", "CD", "C", "XC", "L", "XL", "X", "IX", "V", "IV", "I"]

    # Construir la representación
    result = []
    for i in range(len(values)):
        while n >= values[i]:
            result.append(symbols[i])
            n -= values[i]

    return "".join(result)

def mayor_racha(lista):
    """
    Encuentra la racha más larga de elementos consecutivos iguales
    y devuelve la tupla (elemento, longitud).
    Si hay empate, devuelve la primera.
    Si la lista está vacía, devuelve None.
    """
    if not lista:
        return None

    max_racha = 1
    max_elemento = lista[0]
    racha_actual = 1

    for i in range(1, len(lista)):
        if lista[i] == max_elemento:
            racha_actual += 1
        else:
            racha_actual = 1
            max_elemento = lista[i]

    if racha_actual > max_racha:
        max_racha = racha_actual
        max_elemento = lista[-1]

    return (max_elemento, max_racha)

def a_camel(s: str) -> str:
    """Convierte un texto en snake_case a camelCase.

    La primera palabra se convierte en minúscula y las siguientes
    en mayúscula inicial, sin guiones bajos.

    Args:
        s: El texto a convertir.

    Returns:
        El texto convertido en camelCase.
    """
    words = s.split()
    result = []
    for word in words:
        if word:
            if word[0].isupper():
                result.append(word[0].lower())
            else:
                result.append(word[0].upper())
            result.append(word[1:].lower())
    return ''.join(result)

def primos(n: int) -> list[int]:
    """Devuelve la lista ordenada de todos los números primos menores o iguales a n."""
    if n < 2:
        return []
    primos = []
    for i in range(2, n + 1):
        es_primo = True
        for j in range(2, int(i**0.5) + 1):
            if i % j == 0:
                es_primo = False
                break
        if es_primo:
            primos.append(i)
    return primos

def comprimir(s: str) -> str:
    """
    Aplica codificación por repeticiones.
    'aaabb' se convierte en 'a3b2'.
    Si la versión comprimida no es más corta que la original,
    devuelve la original sin cambios.
    """
    if not s:
        return s

    # Contar repeticiones de cada carácter
    counts = {}
    for char in s:
        counts[char] = counts.get(char, 0) + 1

    # Construir la versión comprimida
    result = ""
    for char, count in counts.items():
        if count > 1:
            result += char + str(count)
        else:
            result += char

    # Verificar si la versión comprimida es más corta
    if len(result) <= len(s):
        return result
    else:
        return s

def balanceado(s: str) -> bool:
    """
    Verifica si los parentesis, corchetes y llaves del texto están correctamente
    balanceados y anidados.

    Args:
        s: El texto a verificar.

    Returns:
        True si el texto está balanceado, False en caso contrario.
    """
    openers = {'(', '[', '{'}
    closers = {')', ']', '}'}
    stack = []

    for char in s:
        if char in openers:
            stack.append(char)
        elif char in closers:
            if not stack:
                return False
            top = stack.pop()
            if top != char:
                return False

    return len(stack) == 0

def anidar(plano: dict) -> dict:
    """
    Recursivamente convierte un dict de claves con puntos en un dict anidado.

    Ejemplo:
        {'a.b': 1} -> {'a': {'b': 1}}
        {'a.b.c': 2} -> {'a': {'b': {'c': 2}}}
        {'a.b.c.d': 3} -> {'a': {'b': {'c': {'d': 3}}}}

    Args:
        plano: Un diccionario que puede contener claves con puntos (ej: 'a.b')
                o sin puntos (ej: 'a').

    Returns:
        Un diccionario anidado donde cada nivel de puntos se agrupa en un nuevo nivel.
    """
    if not plano:
        return {}

    if len(plano) == 1:
        return plano

    # Si la clave tiene puntos, agrupa los valores bajo esa clave
    if '.' in plano:
        clave = plano.split('.')[0]
        valores = [plano[k] for k in plano if k != '.']
        return {clave: anidar(valores)}

    # Si no hay puntos, el valor es un solo elemento
    return plano

def parsear_query(s: str) -> dict:
    """
    Convierte un query string tipo 'a=1&b=2' en un dict {'a':'1','b':'2'}.
    Una clave sin valor ('c=') queda con string vacio.
    String vacio devuelve dict vacio.
    """
    if not s:
        return {}
    result = {}
    for part in s.split("&"):
        if "=" in part:
            key, value = part.split("=", 1)
            result[key] = value
    return result

def sumar_romanos(a: str, b: str) -> str:
    """
    Suma dos números romanos y devuelve el resultado en formato romano.

    Args:
        a: Primer número en formato romano.
        b: Segundo número en formato romano.

    Returns:
        El resultado de la suma en formato romano.

    Raises:
        ValueError: Si los números no están en formato romano válido.
    """
    def valor_romano(s: str) -> int:
        """Convierte un string romano a entero."""
        valores = {
            "I": 1, "V": 5, "X": 10,
            "L": 50, "C": 100, "D": 500, "M": 1000
        }
        if not s:
            raise ValueError("El número romano está vacío.")
        if len(s) == 1:
            return valores.get(s, 0)
        if s[-1] == s[-2]:
            raise ValueError("No se permiten repetidos en el romano.")
        return sum(valores.get(c, 0) for c in s)

    def romano_de_intero(n: int) -> str:
        """Convierte un entero a string romano."""
        if n == 0:
            return "0"
        if n < 0:
            return "-" + romano_de_intero(-n)
        if n == 0:
            return "0"
        if n < 10:
            return str(n)
        if n < 50:
            return "V" + romano_de_intero(n - 5)
        if n < 100:
            return "C" + romano_de_intero(n - 100)
        if n < 500:
            return "D" + romano_de_intero(n - 500)
        if n < 1000:
            return "M" + romano_de_intero(n - 1000)
        raise ValueError("El número es demasiado grande para ser representado en romano.")

    a_val = valor_romano(a)
    b_val = valor_romano(b)
    resultado = a_val + b_val

    if resultado < 0:
        return "-" + romano_de_intero(-resultado)
    elif resultado == 0:
        return "0"
    else:
        return romano_de_intero(resultado)

def con_reintentos(fn, veces):
    """
    Ejecuta fn() y, si lanza una excepción, la reintenta hasta 'veces' intentos en total.
    Si todos los intentos fallan, vuelve a lanzar la última excepción.

    Args:
        fn: Función que puede lanzar excepciones.
        veces: Número máximo de intentos permitidos.

    Returns:
        El resultado de la primera función que no lanza excepción.
    """
    for _ in range(veces):
        try:
            return fn()
        except Exception:
            continue
    raise RuntimeError("Todos los intentos fallaron")
